using System.Collections.Generic;using System.Linq;using HabitatShift.Core;using UnityEngine;
namespace HabitatShift.LevelLabR10 { public sealed class R10TopologyData { public List<HashSet<Vector2Int>> components=new List<HashSet<Vector2Int>>(); public HashSet<Vector2Int> articulation=new HashSet<Vector2Int>(); public HashSet<Vector2Int> corridors=new HashSet<Vector2Int>(); public HashSet<Vector2Int> chokes=new HashSet<Vector2Int>(); }
public static class R10Topology { static readonly Vector2Int[] D={Vector2Int.up,Vector2Int.down,Vector2Int.left,Vector2Int.right}; public static HashSet<Vector2Int> Cells(LevelDto l){var a=l.playableMask==null||l.playableMask.Length==0?Enumerable.Range(0,l.cols).SelectMany(x=>Enumerable.Range(0,l.rows).Select(y=>new Vector2Int(x,y))):l.playableMask.Select(x=>new Vector2Int(x.x,x.y));var s=new HashSet<Vector2Int>(a);foreach(var o in l.obstacles??new IntPair[0])s.Remove(new Vector2Int(o.x,o.y));return s;} public static R10TopologyData Analyze(LevelDto l){var cells=Cells(l);var d=new R10TopologyData();var rest=new HashSet<Vector2Int>(cells);while(rest.Count>0){var c=new HashSet<Vector2Int>();var q=new Queue<Vector2Int>();q.Enqueue(rest.First());rest.Remove(q.Peek());while(q.Count>0){var p=q.Dequeue();c.Add(p);foreach(var v in D)if(rest.Remove(p+v))q.Enqueue(p+v);}d.components.Add(c);}foreach(var c in cells){var n=D.Count(x=>cells.Contains(c+x));if(n<=2)d.corridors.Add(c);var copy=new HashSet<Vector2Int>(cells);copy.Remove(c);if(copy.Count>0&&Count(copy)>d.components.Count){d.articulation.Add(c);d.chokes.Add(c);}}return d;} static int Count(HashSet<Vector2Int>s){var copy=new HashSet<Vector2Int>(s);int n=0;while(copy.Count>0){n++;var q=new Queue<Vector2Int>();q.Enqueue(copy.First());copy.Remove(q.Peek());while(q.Count>0){var p=q.Dequeue();foreach(var v in D)if(copy.Remove(p+v))q.Enqueue(p+v);}}return n;} } }
#endif